// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetInfo What the login page shows before anyone is logged in.
	// (GET /api/v1/info)
	GetInfo(w http.ResponseWriter, r *http.Request)
	// Login Log in with an SMB username and password.
	// (POST /api/v1/login)
	Login(w http.ResponseWriter, r *http.Request, params LoginParams)
	// Logout End the session and its SMB session.
	// (POST /api/v1/logout)
	Logout(w http.ResponseWriter, r *http.Request, params LogoutParams)
	// GetMe The current session.
	// (GET /api/v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListShares The shares the server lists for this user.
	// (GET /api/v1/shares)
	ListShares(w http.ResponseWriter, r *http.Request)
	// CreateArchive Prepare a ZIP of files and folders, for downloading.
	// (POST /api/v1/shares/{share}/archive)
	CreateArchive(w http.ResponseWriter, r *http.Request, share ShareName, params CreateArchiveParams)
	// SaveArchive Pack files and folders into a ZIP file on the share.
	// (POST /api/v1/shares/{share}/archive-to-share)
	SaveArchive(w http.ResponseWriter, r *http.Request, share ShareName, params SaveArchiveParams)
	// GetArchive Download a prepared ZIP.
	// (GET /api/v1/shares/{share}/archive/{ticket})
	GetArchive(w http.ResponseWriter, r *http.Request, share ShareName, ticket string)
	// GetBook An EPUB book's title and chapters, in reading order.
	// (GET /api/v1/shares/{share}/book)
	GetBook(w http.ResponseWriter, r *http.Request, share ShareName, params GetBookParams)
	// GetBookChapter One chapter of an EPUB book, as a tree of text.
	// (GET /api/v1/shares/{share}/book/chapter)
	GetBookChapter(w http.ResponseWriter, r *http.Request, share ShareName, params GetBookChapterParams)
	// GetContent Download a file, streamed, with Range.
	// (GET /api/v1/shares/{share}/content)
	GetContent(w http.ResponseWriter, r *http.Request, share ShareName, params GetContentParams)
	// PutContent Upload a file, streamed.
	// (PUT /api/v1/shares/{share}/content)
	PutContent(w http.ResponseWriter, r *http.Request, share ShareName, params PutContentParams)
	// CopyEntry Copy a file or a folder within a share, or restore a version as a copy.
	// (POST /api/v1/shares/{share}/copy)
	CopyEntry(w http.ResponseWriter, r *http.Request, share ShareName, params CopyEntryParams)
	// DeleteEntry Delete a file or a folder.
	// (DELETE /api/v1/shares/{share}/entries)
	DeleteEntry(w http.ResponseWriter, r *http.Request, share ShareName, params DeleteEntryParams)
	// ListEntries The entries of a folder.
	// (GET /api/v1/shares/{share}/entries)
	ListEntries(w http.ResponseWriter, r *http.Request, share ShareName, params ListEntriesParams)
	// CreateFolder Create a folder.
	// (POST /api/v1/shares/{share}/folders)
	CreateFolder(w http.ResponseWriter, r *http.Request, share ShareName, params CreateFolderParams)
	// GetMetadata What a file says about itself.
	// (GET /api/v1/shares/{share}/metadata)
	GetMetadata(w http.ResponseWriter, r *http.Request, share ShareName, params GetMetadataParams)
	// MoveEntry Rename or move a file or folder within a share.
	// (POST /api/v1/shares/{share}/move)
	MoveEntry(w http.ResponseWriter, r *http.Request, share ShareName, params MoveEntryParams)
	// Search Find names below a folder.
	// (GET /api/v1/shares/{share}/search)
	Search(w http.ResponseWriter, r *http.Request, share ShareName, params SearchParams)
	// GetSheet The first sheet of a spreadsheet, as text.
	// (GET /api/v1/shares/{share}/sheet)
	GetSheet(w http.ResponseWriter, r *http.Request, share ShareName, params GetSheetParams)
	// GetSpace The size and free space of the volume a folder is on.
	// (GET /api/v1/shares/{share}/space)
	GetSpace(w http.ResponseWriter, r *http.Request, share ShareName, params GetSpaceParams)
	// GetDocumentText The plain text of a Word or OpenDocument text, or of a presentation's slides.
	// (GET /api/v1/shares/{share}/text)
	GetDocumentText(w http.ResponseWriter, r *http.Request, share ShareName, params GetDocumentTextParams)
	// GetThumbnail A thumbnail of an image or a recording's cover, made on the fly.
	// (GET /api/v1/shares/{share}/thumbnail)
	GetThumbnail(w http.ResponseWriter, r *http.Request, share ShareName, params GetThumbnailParams)
	// UnpackArchive Unpack a ZIP archive into a new folder on the share.
	// (POST /api/v1/shares/{share}/unpack)
	UnpackArchive(w http.ResponseWriter, r *http.Request, share ShareName, params UnpackArchiveParams)
	// BeginUpload Begin an upload in pieces.
	// (POST /api/v1/shares/{share}/uploads)
	BeginUpload(w http.ResponseWriter, r *http.Request, share ShareName, params BeginUploadParams)
	// DiscardUpload Give an upload up, removing its partial file.
	// (DELETE /api/v1/shares/{share}/uploads/{id})
	DiscardUpload(w http.ResponseWriter, r *http.Request, share ShareName, id UploadId, params DiscardUploadParams)
	// GetUpload How far an upload in pieces has come.
	// (GET /api/v1/shares/{share}/uploads/{id})
	GetUpload(w http.ResponseWriter, r *http.Request, share ShareName, id UploadId, params GetUploadParams)
	// PutUploadPiece Write the next piece of an upload.
	// (PUT /api/v1/shares/{share}/uploads/{id})
	PutUploadPiece(w http.ResponseWriter, r *http.Request, share ShareName, id UploadId, params PutUploadPieceParams)
	// FinishUpload Make a complete upload the file.
	// (POST /api/v1/shares/{share}/uploads/{id}/finish)
	FinishUpload(w http.ResponseWriter, r *http.Request, share ShareName, id UploadId, params FinishUploadParams)
	// GetUsage Add up what a folder holds.
	// (GET /api/v1/shares/{share}/usage)
	GetUsage(w http.ResponseWriter, r *http.Request, share ShareName, params GetUsageParams)
	// ListVersions The previous versions of a file or a folder.
	// (GET /api/v1/shares/{share}/versions)
	ListVersions(w http.ResponseWriter, r *http.Request, share ShareName, params ListVersionsParams)
	// ListZip What a ZIP archive holds.
	// (GET /api/v1/shares/{share}/zip)
	ListZip(w http.ResponseWriter, r *http.Request, share ShareName, params ListZipParams)
	// GetZipEntry One file out of a ZIP archive, unpacked as it is sent.
	// (GET /api/v1/shares/{share}/zip/entry)
	GetZipEntry(w http.ResponseWriter, r *http.Request, share ShareName, params GetZipEntryParams)
}

// ServerInterfaceWrapper converts contexts to parameters.
